const product = $('Pick Random Product').first().json;
const geminiRes = $input.all()[0].json;

const postText = geminiRes.candidates?.[0]?.content?.parts?.[0]?.text || "Descubre nuestro nuevo producto en shongyi.com/bazar";

return [{
  json: {
    message: postText,
    link: product.sourceUrl || "https://shongyi.com/bazar",
    imageUrl: product.imageUrl
  }
}];
